void sig(int){stop=1;}
std::vector<std::string> labels(const char*p){std::ifstream f(p);std::vector<std::string>v;std::string s;while(std::getline(f,s))v.push_back(s);return v;} const char* label(NvDsObjectMeta*o,const std::vector<std::string>&v){return o->obj_label[0]?o->obj_label:(o->class_id>=0&&(size_t)o->class_id<v.size()?v[o->class_id].c_str():"unknown");}
std::string redact(const gchar*x,char**v){std::string r=x?x:"";for(int i=1;i<=5;i++){std::string s=v[i];std::string::size_type p=0;while(!s.empty()&&(p=r.find(s,p))!=std::string::npos){r.replace(p,s.size(),"<redacted-hls-url>");p+=18;}}return r;}
GstCaps* caps(GstPad*p){GstCaps*c=gst_pad_get_current_caps(p);return c?c:gst_pad_query_caps(p,nullptr);} bool match(GstCaps*c,const char*s){GstCaps*x=gst_caps_from_string(s);bool ok=c&&x&&gst_caps_can_intersect(c,x);if(x)gst_caps_unref(x);return ok;} void fail(GstElement*e,const char*s){GError*x=g_error_new_literal(GST_STREAM_ERROR,GST_STREAM_ERROR_FAILED,s);gst_element_post_message(e,gst_message_new_error(GST_OBJECT(e),x,nullptr));g_error_free(x);}
GstPadProbeReturn decode(GstPad*p,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;Src*s=(Src*)d;++s->buffers;return GST_PAD_PROBE_OK;} GstPadProbeReturn count(GstPad*,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;Counter*c=(Counter*)d;++c->buffers;return GST_PAD_PROBE_OK;} void hls(GstElement*e,GstPad*p,gpointer d){Src*s=(Src*)d;GstCaps*c=caps(p);if(!match(c,"video/mpegts")){if(c)gst_caps_unref(c);fail(e,"Unsupported HLS output; expected video/mpegts");return;}if(c)gst_caps_unref(c);if(s->ts_linked)return;GstPad*q=gst_element_get_static_pad(s->ts,"sink");if(!q||gst_pad_link(p,q)!=GST_PAD_LINK_OK)fail(e,"Could not link HLS MPEG-TS");else{ s->ts_linked=true;std::cout<<"Source "<<s->id<<": HLS MPEG-TS linked.\n";}if(q)gst_object_unref(q);}
void ts(GstElement*e,GstPad*p,gpointer d){Src*s=(Src*)d;GstCaps*c=caps(p);const GstStructure*z=c?gst_caps_get_structure(c,0):nullptr;const gchar*n=z?gst_structure_get_name(z):nullptr;if(g_strcmp0(n,"video/x-h264")){bool h265=!g_strcmp0(n,"video/x-h265");if(c)gst_caps_unref(c);if(h265)fail(e,"H.265 unsupported; Stage 5B requires H.264");return;}if(c)gst_caps_unref(c);if(s->h264_linked)return;GstPad*q=gst_element_get_static_pad(s->parser,"sink");if(!q||gst_pad_link(p,q)!=GST_PAD_LINK_OK)fail(e,"Could not link HLS H.264");else{s->h264_linked=true;std::cout<<"Source "<<s->id<<": HLS H.264 video linked.\n";}if(q)gst_object_unref(q);}
struct Point { float x,y; };
Point roi_point(const CameraAnalyticsConfig& c,float x,float y){return Point{c.roi_x_min+(c.roi_x_max-c.roi_x_min)*x,c.roi_y_min+(c.roi_y_max-c.roi_y_min)*y};}
bool inside_roi(const CameraAnalyticsConfig& c,const Point& p){return p.x>=c.roi_x_min&&p.x<=c.roi_x_max&&p.y>=c.roi_y_min&&p.y<=c.roi_y_max;}
Side line_side(const CameraAnalyticsConfig& c,const Point& p){const Point a=roi_point(c,c.line_start_x,c.line_start_y),b=roi_point(c,c.line_end_x,c.line_end_y);const float value=(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);return value>c.side_epsilon?SIDE_A:(value<-c.side_epsilon?SIDE_B:SIDE_NONE);}
bool is_person(NvDsObjectMeta* o,const App* a){return o->class_id==PERSON_CLASS_ID&&!g_strcmp0(label(o,a->labels),"person");}
const char* side_name(Side side){return side==SIDE_A?"A":(side==SIDE_B?"B":"NONE");}
void line_debug(const App* a,guint64 object_id,const char* event,Side side,const Point* point=nullptr){if(!a->line_debug)return;std::ostringstream message;message<<"LINE_DEBUG source_id=0 object_id="<<object_id<<" event="<<event<<" side="<<side_name(side);if(point)message<<" x="<<std::fixed<<std::setprecision(3)<<point->x<<" y="<<point->y;std::cout<<message.str()<<'\n';}
void quality_snapshot(const char* event,guint64 object_id,const QualityTrackState& state,const NvDsObjectMeta* object,const Point& point,guint frame_num,Side side){std::cout<<"QUALITY_"<<event<<" source_id=0 object_id="<<object_id<<" confidence="<<std::fixed<<std::setprecision(3)<<object->confidence<<" bbox="<<object->rect_params.left<<","<<object->rect_params.top<<","<<object->rect_params.width<<","<<object->rect_params.height<<" x="<<point.x<<" y="<<point.y<<" frame="<<frame_num<<" track_frames="<<state.track_frames<<" last_seen_frame="<<state.last_seen_frame<<" side="<<side_name(side)<<"\n";}
void quality_track_end(App* a,guint64 object_id,const QualityTrackState& state,const char* reason){const double average=state.track_frames?state.confidence_sum/state.track_frames:0.0;std::cout<<"QUALITY_TRACK_END source_id=0 object_id="<<object_id<<" track_frames="<<state.track_frames<<" avg_confidence="<<std::fixed<<std::setprecision(3)<<average<<" min_confidence="<<state.min_confidence<<" max_confidence="<<state.max_confidence<<" last_x="<<state.last_x<<" last_y="<<state.last_y<<" reason="<<reason<<"\n";a->quality_track_lengths.push_back(state.track_frames);}
void quality_possible_id_switch(App* a,guint64 new_id,const Point& point,guint frame_num){guint64 old_id=static_cast<guint64>(-1);float best_distance=QUALITY_ID_SWITCH_DISTANCE;guint best_gap=0;for(std::map<guint64,QualityTrackState>::const_iterator it=a->quality_tracks.begin();it!=a->quality_tracks.end();++it){if(it->first==new_id||frame_num<=it->second.last_seen_frame)continue;const guint gap=frame_num-it->second.last_seen_frame;if(gap>QUALITY_ID_SWITCH_WINDOW)continue;const float dx=point.x-it->second.last_x,dy=point.y-it->second.last_y,distance=std::sqrt(dx*dx+dy*dy);if(distance<=best_distance){old_id=it->first;best_distance=distance;best_gap=gap;}}if(old_id!=static_cast<guint64>(-1)){++a->quality_possible_id_switches;std::cout<<"QUALITY_POSSIBLE_ID_SWITCH source_id=0 old_id="<<old_id<<" new_id="<<new_id<<" distance="<<std::fixed<<std::setprecision(3)<<best_distance<<" frame_gap="<<best_gap<<"\n";}}
void process_quality_track(App* a,NvDsFrameMeta* frame,NvDsObjectMeta* object){const CameraAnalyticsConfig& c=kCamera0Analytics;if(!a->quality_debug||frame->source_id!=c.source_id||object->object_id==static_cast<guint64>(-1)||!frame->pipeline_width||!frame->pipeline_height)return;const guint frame_num=static_cast<guint>(frame->frame_num);const Point point={(object->rect_params.left+object->rect_params.width/2.0f)/frame->pipeline_width,(object->rect_params.top+object->rect_params.height)/frame->pipeline_height};const float confidence=object->confidence;std::map<guint64,QualityTrackState>::iterator it=a->quality_tracks.find(object->object_id);if(it==a->quality_tracks.end()){quality_possible_id_switch(a,object->object_id,point,frame_num);const QualityTrackState state={frame_num,frame_num,1,confidence,confidence,confidence,confidence,point.x,point.y};a->quality_tracks[object->object_id]=state;++a->quality_tracks_total;quality_snapshot("TRACK_START",object->object_id,state,object,point,frame_num,line_side(c,point));return;}QualityTrackState& state=it->second;const float dx=point.x-state.last_x,dy=point.y-state.last_y,confidence_delta=confidence-state.last_confidence;++state.track_frames;state.last_seen_frame=frame_num;state.confidence_sum+=confidence;state.min_confidence=std::min(state.min_confidence,confidence);state.max_confidence=std::max(state.max_confidence,confidence);if(std::fabs(confidence_delta)>QUALITY_CONFIDENCE_DELTA)std::cout<<"QUALITY_CONFIDENCE_CHANGE source_id=0 object_id="<<object->object_id<<" delta="<<std::fixed<<std::setprecision(3)<<confidence_delta<<" confidence="<<confidence<<" frame="<<frame_num<<"\n";if(std::fabs(dx)>QUALITY_JUMP_DELTA||std::fabs(dy)>QUALITY_JUMP_DELTA){++a->quality_bbox_jumps;std::cout<<"QUALITY_JUMP source_id=0 object_id="<<object->object_id<<" dx="<<std::fixed<<std::setprecision(3)<<dx<<" dy="<<dy<<" confidence="<<confidence<<" frame="<<frame_num<<"\n";}state.last_confidence=confidence;state.last_x=point.x;state.last_y=point.y;if(state.track_frames==5||state.track_frames==15||state.track_frames==30)quality_snapshot("TRACK_CHECKPOINT",object->object_id,state,object,point,frame_num,line_side(c,point));}
void cleanup_quality_tracks(App* a,guint frame_num){if(!a->quality_debug)return;for(std::map<guint64,QualityTrackState>::iterator it=a->quality_tracks.begin();it!=a->quality_tracks.end();){if(frame_num>it->second.last_seen_frame+TRACK_STATE_STALE_FRAMES){quality_track_end(a,it->first,it->second,"STALE_REMOVED");it=a->quality_tracks.erase(it);}else ++it;}}
void finish_quality_tracks(App* a){if(!a->quality_debug)return;for(std::map<guint64,QualityTrackState>::iterator it=a->quality_tracks.begin();it!=a->quality_tracks.end();){quality_track_end(a,it->first,it->second,"SHUTDOWN");it=a->quality_tracks.erase(it);}}
void quality_summary(App* a){if(!a->quality_debug)return;guint under5=0,from5to14=0,from15to29=0,atleast30=0;double total=0.0;for(std::vector<guint>::const_iterator it=a->quality_track_lengths.begin();it!=a->quality_track_lengths.end();++it){total+=*it;if(*it<5)++under5;else if(*it<15)++from5to14;else if(*it<30)++from15to29;else ++atleast30;}double median=0.0;if(!a->quality_track_lengths.empty()){std::vector<guint> lengths=a->quality_track_lengths;std::sort(lengths.begin(),lengths.end());const size_t middle=lengths.size()/2;median=lengths.size()%2?lengths[middle]:(lengths[middle-1]+lengths[middle])/2.0;}std::cout<<"QUALITY SUMMARY\nperson tracks total: "<<a->quality_tracks_total<<"\ntracks <5 frames: "<<under5<<"\ntracks 5-14 frames: "<<from5to14<<"\ntracks 15-29 frames: "<<from15to29<<"\ntracks >=30 frames: "<<atleast30<<"\navg track length: "<<std::fixed<<std::setprecision(2)<<(a->quality_track_lengths.empty()?0.0:total/a->quality_track_lengths.size())<<"\nmedian track length: "<<median<<"\npossible id switches: "<<a->quality_possible_id_switches<<"\nbbox jumps: "<<a->quality_bbox_jumps<<"\nline crossings: "<<a->quality_line_crossings<<"\n";}void cleanup_line_tracks(App* a,guint frame_num){for(std::map<guint64,TrackState>::iterator it=a->line_tracks.begin();it!=a->line_tracks.end();){if(frame_num>it->second.last_seen_frame+TRACK_STATE_STALE_FRAMES){line_debug(a,it->first,"STALE_REMOVED",it->second.side);it=a->line_tracks.erase(it);}else ++it;}}
void process_person_crossing(App* a,NvDsFrameMeta* m,NvDsObjectMeta* o){const CameraAnalyticsConfig& c=kCamera0Analytics;if(!c.enabled||m->source_id!=c.source_id||o->object_id==static_cast<guint64>(-1)||!m->pipeline_width||!m->pipeline_height)return;const Point p={(o->rect_params.left+o->rect_params.width/2.0f)/m->pipeline_width,(o->rect_params.top+o->rect_params.height)/m->pipeline_height};const guint frame_num=static_cast<guint>(m->frame_num);std::map<guint64,TrackState>::iterator it=a->line_tracks.find(o->object_id);if(!inside_roi(c,p)){if(it!=a->line_tracks.end()){if(it->second.in_roi)line_debug(a,o->object_id,"LEAVE_ROI",it->second.side,&p);it->second.side=SIDE_NONE;it->second.candidate_side=SIDE_NONE;it->second.candidate_frames=0;it->second.last_seen_frame=frame_num;it->second.in_roi=false;it->second.near_line=false;}return;}const Side side=line_side(c,p);if(it==a->line_tracks.end()){TrackState state={side,SIDE_NONE,0,frame_num,true,side==SIDE_NONE};a->line_tracks[o->object_id]=state;line_debug(a,o->object_id,"ENTER_ROI",side,&p);if(side==SIDE_NONE)line_debug(a,o->object_id,"NEAR_LINE",side,&p);else line_debug(a,o->object_id,"VALID_SIDE",side,&p);return;}TrackState& state=it->second;state.last_seen_frame=frame_num;if(!state.in_roi){state.in_roi=true;line_debug(a,o->object_id,"ENTER_ROI",side,&p);}if(side==SIDE_NONE){if(!state.near_line)line_debug(a,o->object_id,"NEAR_LINE",state.side,&p);state.near_line=true;return;}state.near_line=false;if(state.side==SIDE_NONE){state.side=side;state.candidate_side=SIDE_NONE;state.candidate_frames=0;line_debug(a,o->object_id,"VALID_SIDE",side,&p);return;}if(state.side==side){state.candidate_side=SIDE_NONE;state.candidate_frames=0;return;}if(state.candidate_side==side)++state.candidate_frames;else{state.candidate_side=side;state.candidate_frames=1;}if(state.candidate_frames<2)return;const Side previous_side=state.side;if(a->line_debug){std::ostringstream message;message<<"LINE_DEBUG source_id=0 object_id="<<o->object_id<<" event=SIDE_CONFIRMED from="<<side_name(previous_side)<<" to="<<side_name(side)<<" x="<<std::fixed<<std::setprecision(3)<<p.x<<" y="<<p.y;std::cout<<message.str()<<"\n";}const bool in=state.side==SIDE_A&&side==SIDE_B?c.side_a_to_b_is_in:!c.side_a_to_b_is_in;if(in)++a->people_in;else ++a->people_out;if(a->quality_debug)++a->quality_line_crossings;std::cout<<"LINE_CROSSING source_id=0 object_id="<<o->object_id<<" class=person direction="<<(in?"IN":"OUT")<<" people_in="<<a->people_in<<" people_out="<<a->people_out<<'\n';state.side=side;state.candidate_side=SIDE_NONE;state.candidate_frames=0;}bool is_vehicle(NvDsObjectMeta* o,const App* a){if(o->class_id!=CAR_CLASS_ID&&o->class_id!=MOTORCYCLE_CLASS_ID&&o->class_id!=BUS_CLASS_ID)return false;const char* name=label(o,a->labels);return !g_strcmp0(name,"car")||!g_strcmp0(name,"motorcycle")||!g_strcmp0(name,"bus");}GstPadProbeReturn filter_source0_vehicle_metadata(GstPad*,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;App*a=(App*)d;NvDsBatchMeta*b=gst_buffer_get_nvds_batch_meta(GST_PAD_PROBE_INFO_BUFFER(i));if(!b)return GST_PAD_PROBE_OK;for(NvDsMetaList*f=b->frame_meta_list;f;f=f->next){NvDsFrameMeta*m=(NvDsFrameMeta*)f->data;if(!m||m->source_id!=0)continue;for(NvDsMetaList*x=m->obj_meta_list;x;){NvDsMetaList*next=x->next;NvDsObjectMeta*o=(NvDsObjectMeta*)x->data;if(o&&!is_vehicle(o,a))nvds_remove_obj_meta_from_frame(m,o);x=next;}}return GST_PAD_PROBE_OK;}
bool inside_vehicle_roi(const Point& p){return p.x>=kStage7Geometry.x_min&&p.x<=kStage7Geometry.x_max&&p.y>=kStage7Geometry.y_min&&p.y<=kStage7Geometry.y_max;}
struct VehicleLineEvaluation { Point point,a,b; float signed_distance,t; bool projection_in_bounds,in_gate; Side side; };
struct VehicleSegmentIntersection { bool intersects; float line_t,motion_t; };
VehicleLineEvaluation vehicle_line_evaluate(const VehicleLineConfig& line,const NvDsFrameMeta* frame,const NvDsObjectMeta* object){const Point point={object->rect_params.left+object->rect_params.width/2.0f,object->rect_params.top+object->rect_params.height};const Point a={line.start_x*frame->pipeline_width,line.start_y*frame->pipeline_height},b={line.end_x*frame->pipeline_width,line.end_y*frame->pipeline_height};const float dx=b.x-a.x,dy=b.y-a.y,length=std::sqrt(dx*dx+dy*dy),denominator=dx*dx+dy*dy;VehicleLineEvaluation result={point,a,b,0.0f,0.0f,false,false,SIDE_NONE};if(length<=0.0f||denominator<=0.0f)return result;result.signed_distance=(dx*(point.y-a.y)-dy*(point.x-a.x))/length;result.t=((point.x-a.x)*dx+(point.y-a.y)*dy)/denominator;result.projection_in_bounds=result.t>=0.0f&&result.t<=1.0f;if(!result.projection_in_bounds)return result;result.in_gate=std::fabs(result.signed_distance)<=kVehicleLineGateHalfWidthPx;result.side=result.signed_distance<-kVehicleLineSideDeadbandPx?SIDE_A:(result.signed_distance>kVehicleLineSideDeadbandPx?SIDE_B:SIDE_NONE);return result;}
VehicleSegmentIntersection vehicle_segment_intersection(const Point& a,const Point& b,const Point& previous,const Point& current){const float rx=b.x-a.x,ry=b.y-a.y,sx=current.x-previous.x,sy=current.y-previous.y,denominator=rx*sy-ry*sx;if(std::fabs(denominator)<0.0001f)return VehicleSegmentIntersection{false,0.0f,0.0f};const float qpx=previous.x-a.x,qpy=previous.y-a.y,line_t=(qpx*sy-qpy*sx)/denominator,motion_t=(qpx*ry-qpy*rx)/denominator;return VehicleSegmentIntersection{line_t>=0.0f&&line_t<=1.0f&&motion_t>=0.0f&&motion_t<=1.0f,line_t,motion_t};}
void vehicle_line_debug(const App* a,const VehicleLineConfig& line,guint64 object_id,const char* event,Side from=SIDE_NONE,Side to=SIDE_NONE){if(!a->vehicle_line_debug)return;std::cout<<"VEHICLE_LINE_DEBUG line="<<line.name<<" object_id="<<object_id<<" event="<<event;if(from!=SIDE_NONE||to!=SIDE_NONE)std::cout<<" from="<<side_name(from)<<" to="<<side_name(to);std::cout<<'\n';}
void vehicle_line_zone_near_debug(const App* a,const VehicleLineConfig& line,guint64 object_id,guint frame_num,const VehicleLineEvaluation& evaluation){if(!a->vehicle_line_zone_debug)return;std::cout<<"VEHICLE_LINE_ZONE_NEAR object_id="<<object_id<<" frame="<<frame_num<<" line="<<line.name<<" signed_distance_px="<<std::fixed<<std::setprecision(3)<<evaluation.signed_distance<<" t="<<evaluation.t<<'\n';}
Side vehicle_line_signed_side(const Point& point,const Point& a,const Point& b){const float dx=b.x-a.x,dy=b.y-a.y,length=std::sqrt(dx*dx+dy*dy);if(length<=0.0f)return SIDE_NONE;const float distance=(dx*(point.y-a.y)-dy*(point.x-a.x))/length;return distance<0.0f?SIDE_A:(distance>0.0f?SIDE_B:SIDE_NONE);}
void vehicle_line_pending_debug(const App* a,const VehicleLineConfig& line,guint64 object_id,const char* event,Side from,Side to,guint frame_num,float line_t=0.0f,float motion_t=0.0f,const char* reason=nullptr){if(!a->vehicle_line_debug)return;std::cout<<"VEHICLE_LINE_DEBUG line="<<line.name<<" object_id="<<object_id<<" event="<<event<<" from="<<side_name(from)<<" to="<<side_name(to)<<" frame="<<frame_num;if(!g_strcmp0(event,"SEGMENT_INTERSECTION_PENDING")||!g_strcmp0(event,"SEGMENT_INTERSECTION_CONFIRMED"))std::cout<<" intersection_t_line="<<line_t<<" intersection_t_motion="<<motion_t;if(reason)std::cout<<" reason="<<reason;std::cout<<'\n';}
void clear_vehicle_pending(App* a,const VehicleLineConfig& line,guint64 object_id,VehicleLineState& state,const char* reason){if(!state.pending_crossing_valid)return;vehicle_line_pending_debug(a,line,object_id,"CROSSING_DROPPED",state.pending_from_side,state.pending_to_side,state.pending_frame,state.pending_line_t,state.pending_motion_t,reason);state.pending_crossing_valid=false;state.pending_direct_intersection=false;state.pending_from_side=SIDE_NONE;state.pending_to_side=SIDE_NONE;}
void enqueue_vehicle_crossing_event(App* a,const VehicleLineConfig& line,NvDsObjectMeta* object,const char* direction){if(!a->event_sender||!direction)return;const EventPayload event=make_line_crossing_event(a->run_id,line.name,label(object,a->labels),static_cast<std::uint64_t>(object->object_id),direction,object->confidence);a->event_sender->enqueue(event);}
void process_vehicle_line(App* a,NvDsFrameMeta* frame,NvDsObjectMeta* object,guint line_id){if(frame->source_id!=0||object->object_id==static_cast<guint64>(-1)||!frame->pipeline_width||!frame->pipeline_height)return;const VehicleLineConfig& line=kVehicleLines[line_id];const VehicleLineEvaluation e=vehicle_line_evaluate(line,frame,object);const Point normalized={e.point.x/frame->pipeline_width,e.point.y/frame->pipeline_height};const guint f=static_cast<guint>(frame->frame_num);std::map<guint64,VehicleLineState>& tracks=a->vehicle_tracks[line_id];std::map<guint64,VehicleLineState>::iterator it=tracks.find(object->object_id);if(!inside_vehicle_roi(normalized)){if(it!=tracks.end()){clear_vehicle_pending(a,line,object->object_id,it->second,"LEAVE_ROI");it->second.in_roi=false;it->second.in_gate=false;it->second.gate_seen=false;it->second.side=SIDE_NONE;it->second.candidate_side=SIDE_NONE;it->second.candidate_frames=0;it->second.last_seen_frame=f;it->second.previous_x=e.point.x;it->second.previous_y=e.point.y;}return;}if(it==tracks.end()){VehicleLineState state;state.side=e.side;state.last_seen_frame=f;state.previous_x=e.point.x;state.previous_y=e.point.y;state.in_roi=true;state.in_gate=e.in_gate;state.gate_seen=e.in_gate;state.gate_frame=e.in_gate?f:0;tracks[object->object_id]=state;if(e.in_gate)vehicle_line_debug(a,line,object->object_id,"GATE_ENTER");return;}VehicleLineState& state=it->second;const Point previous={state.previous_x,state.previous_y};state.previous_x=e.point.x;state.previous_y=e.point.y;state.last_seen_frame=f;const bool was_in_gate=state.in_gate;state.in_gate=e.in_gate;if(e.in_gate){if(!was_in_gate)vehicle_line_debug(a,line,object->object_id,"GATE_ENTER",state.side,e.side);state.gate_seen=true;state.gate_frame=f;}else if(was_in_gate)vehicle_line_debug(a,line,object->object_id,"GATE_EXIT",state.side,e.side);if(state.pending_crossing_valid&&f>state.pending_frame+kVehiclePendingCrossingMaxFrames)clear_vehicle_pending(a,line,object->object_id,state,"STALE");if(state.gate_seen&&!state.in_gate&&f>state.gate_frame+kVehiclePendingCrossingMaxFrames){if(state.pending_crossing_valid&&!state.pending_direct_intersection)clear_vehicle_pending(a,line,object->object_id,state,"GATE_STALE");state.gate_seen=false;}const VehicleSegmentIntersection x=vehicle_segment_intersection(e.a,e.b,previous,e.point);if(x.intersects){const Side from=vehicle_line_signed_side(previous,e.a,e.b),to=vehicle_line_signed_side(e.point,e.a,e.b);if(from!=SIDE_NONE&&to!=SIDE_NONE&&from!=to){if(state.pending_crossing_valid&&(state.pending_from_side!=from||state.pending_to_side!=to))clear_vehicle_pending(a,line,object->object_id,state,"REPLACED");state.pending_crossing_valid=true;state.pending_direct_intersection=true;state.pending_from_side=from;state.pending_to_side=to;state.pending_frame=f;state.pending_line_t=x.line_t;state.pending_motion_t=x.motion_t;vehicle_line_debug(a,line,object->object_id,"SEGMENT_INTERSECTION_PENDING",from,to);}}if(!e.projection_in_bounds){state.candidate_side=SIDE_NONE;state.candidate_frames=0;clear_vehicle_pending(a,line,object->object_id,state,"OUTSIDE_BOUNDED_SEGMENT");state.gate_seen=false;return;}const Side side=e.side;if(side==SIDE_NONE)return;if(state.side==SIDE_NONE){state.side=side;state.candidate_side=SIDE_NONE;state.candidate_frames=0;clear_vehicle_pending(a,line,object->object_id,state,"BASELINE_RESET");state.gate_seen=false;vehicle_line_debug(a,line,object->object_id,"STABLE_SIDE",side,side);return;}if(state.side==side){state.candidate_side=SIDE_NONE;state.candidate_frames=0;if(state.pending_crossing_valid)clear_vehicle_pending(a,line,object->object_id,state,"TRANSITION_REVERSED");if(!state.in_gate)state.gate_seen=false;return;}if(state.candidate_side==side)++state.candidate_frames;else{state.candidate_side=side;state.candidate_frames=1;if(state.pending_crossing_valid&&(state.pending_from_side!=state.side||state.pending_to_side!=side))clear_vehicle_pending(a,line,object->object_id,state,"SIDE_MISMATCH");if(!state.pending_crossing_valid&&state.gate_seen){state.pending_crossing_valid=true;state.pending_direct_intersection=false;state.pending_from_side=state.side;state.pending_to_side=side;state.pending_frame=f;}vehicle_line_debug(a,line,object->object_id,"CROSSING_PENDING",state.side,side);}if(state.candidate_frames<2)return;const Side previous_side=state.side;const bool pending_matches=state.pending_crossing_valid&&state.pending_from_side==previous_side&&state.pending_to_side==side;if(!pending_matches){if(state.pending_crossing_valid)clear_vehicle_pending(a,line,object->object_id,state,"SIDE_MISMATCH");else vehicle_line_debug(a,line,object->object_id,"CROSSING_DROPPED",previous_side,side);state.side=side;state.candidate_side=SIDE_NONE;state.candidate_frames=0;state.gate_seen=false;vehicle_line_debug(a,line,object->object_id,"STABLE_SIDE",side,side);return;}vehicle_line_debug(a,line,object->object_id,"CROSSING_CONFIRMED",previous_side,side);bool counted=false;const char* direction=nullptr;const char* reason="ALREADY_COUNTED";if(!state.counted){if(line.right_to_left_only){if(e.point.x<previous.x){++a->vehicle_counters.blue_right_to_left;counted=true;direction="RIGHT_TO_LEFT";if(a->vehicle_line_debug)std::cout<<"LINE_CROSSING line=blue object_id="<<object->object_id<<" class="<<label(object,a->labels)<<" direction=RIGHT_TO_LEFT blue_total="<<a->vehicle_counters.blue_right_to_left<<" intersection_t_line="<<state.pending_line_t<<" intersection_t_motion="<<state.pending_motion_t<<'\n';}else{++a->vehicle_counters.blue_direction_rejected;reason="DIRECTION_REJECTED";}}else if(line_id==VEHICLE_RED){if(e.point.y<previous.y){++a->vehicle_counters.red_direction_1;counted=true;direction="BOTTOM_TO_TOP";if(a->vehicle_line_debug)std::cout<<"LINE_CROSSING line=red object_id="<<object->object_id<<" class="<<label(object,a->labels)<<" direction=BOTTOM_TO_TOP red_total="<<(a->vehicle_counters.red_direction_1+a->vehicle_counters.red_direction_2)<<" intersection_t_line="<<state.pending_line_t<<" intersection_t_motion="<<state.pending_motion_t<<'\n';}else reason="DIRECTION_REJECTED";}else{const bool left_to_right=e.point.x>previous.x;if(left_to_right)++a->vehicle_counters.green_direction_1;else ++a->vehicle_counters.green_direction_2;counted=true;direction=left_to_right?"LEFT_TO_RIGHT":"RIGHT_TO_LEFT";if(a->vehicle_line_debug)std::cout<<"LINE_CROSSING line=green object_id="<<object->object_id<<" class="<<label(object,a->labels)<<" direction="<<(left_to_right?"LEFT_TO_RIGHT":"RIGHT_TO_LEFT")<<" green_total="<<(a->vehicle_counters.green_direction_1+a->vehicle_counters.green_direction_2)<<" intersection_t_line="<<state.pending_line_t<<" intersection_t_motion="<<state.pending_motion_t<<'\n';}}if(counted){state.counted=true;reason="ACCEPTED";enqueue_vehicle_crossing_event(a,line,object,direction);}clear_vehicle_pending(a,line,object->object_id,state,reason);state.side=side;state.candidate_side=SIDE_NONE;state.candidate_frames=0;state.gate_seen=false;vehicle_line_debug(a,line,object->object_id,"STABLE_SIDE",side,side);}void cleanup_vehicle_tracks(App* a,guint frame_num){for(guint line_id=0;line_id<VEHICLE_LINE_COUNT;++line_id){const VehicleLineConfig& line=kVehicleLines[line_id];std::map<guint64,VehicleLineState>& tracks=a->vehicle_tracks[line_id];for(std::map<guint64,VehicleLineState>::iterator it=tracks.begin();it!=tracks.end();){if(frame_num>it->second.last_seen_frame+TRACK_STATE_STALE_FRAMES){clear_vehicle_pending(a,line,it->first,it->second,"STALE_REMOVED");it=tracks.erase(it);}else ++it;}}}void vehicle_quality_snapshot(const char* event,const VehicleQualityTrackState& state,const NvDsObjectMeta* object,const Point& point,guint frame_num){std::cout<<"VEHICLE_QUALITY_"<<event<<" source_id="<<state.source_id<<" object_id="<<state.object_id<<" class="<<state.object_label<<" confidence="<<std::fixed<<std::setprecision(3)<<object->confidence<<" bbox="<<object->rect_params.left<<","<<object->rect_params.top<<","<<object->rect_params.width<<","<<object->rect_params.height<<" x="<<point.x<<" y="<<point.y<<" frame="<<frame_num;std::cout<<" track_frames="<<state.observed_frames;std::cout<<'\n';}
void vehicle_quality_track_end(App* a,const VehicleQualityTrackState& state,const char* reason){const double average=state.observed_frames?state.confidence_sum/state.observed_frames:0.0;std::cout<<"VEHICLE_QUALITY_TRACK_END source_id="<<state.source_id<<" object_id="<<state.object_id<<" class="<<state.object_label<<" track_frames="<<state.observed_frames<<" avg_confidence="<<std::fixed<<std::setprecision(3)<<average<<" min_confidence="<<state.min_confidence<<" max_confidence="<<state.max_confidence<<" last_x="<<state.last_x<<" last_y="<<state.last_y<<" max_observation_gap="<<state.max_observation_gap<<" reason="<<reason<<'\n';a->vehicle_quality_track_lengths.push_back(state.observed_frames);}
void vehicle_quality_possible_id_switch(App* a,const VehicleQualityTrackState& state,const Point& point,guint frame_num){guint64 old_id=static_cast<guint64>(-1);float best_distance=VEHICLE_QUALITY_ID_SWITCH_DISTANCE;guint best_gap=0;for(std::map<guint64,VehicleQualityTrackState>::const_iterator it=a->vehicle_quality_tracks.begin();it!=a->vehicle_quality_tracks.end();++it){const VehicleQualityTrackState& old=it->second;if(old.object_id==state.object_id||old.class_id!=state.class_id||frame_num<=old.last_seen_frame)continue;const guint gap=frame_num-old.last_seen_frame;if(gap>QUALITY_ID_SWITCH_WINDOW)continue;const float dx=point.x-old.last_x,dy=point.y-old.last_y,distance=std::sqrt(dx*dx+dy*dy);if(distance<=best_distance){old_id=old.object_id;best_distance=distance;best_gap=gap;}}if(old_id!=static_cast<guint64>(-1)){++a->vehicle_quality_id_switches;std::cout<<"VEHICLE_QUALITY_POSSIBLE_ID_SWITCH source_id=0 old_id="<<old_id<<" new_id="<<state.object_id<<" class="<<state.object_label<<" distance="<<std::fixed<<std::setprecision(3)<<best_distance<<" frame_gap="<<best_gap<<'\n';}}
void process_vehicle_quality_track(App* a,NvDsFrameMeta* frame,NvDsObjectMeta* object){if(!a->vehicle_quality_debug||frame->source_id!=0||object->object_id==static_cast<guint64>(-1)||!frame->pipeline_width||!frame->pipeline_height)return;const guint frame_num=static_cast<guint>(frame->frame_num);const Point point={(object->rect_params.left+object->rect_params.width/2.0f)/frame->pipeline_width,(object->rect_params.top+object->rect_params.height)/frame->pipeline_height};const float confidence=object->confidence,width=object->rect_params.width,height=object->rect_params.height,area=width*height;std::map<guint64,VehicleQualityTrackState>::iterator it=a->vehicle_quality_tracks.find(object->object_id);if(it==a->vehicle_quality_tracks.end()){VehicleQualityTrackState state={};state.source_id=frame->source_id;state.object_id=object->object_id;state.class_id=object->class_id;state.object_label=label(object,a->labels);state.first_frame=frame_num;state.last_seen_frame=frame_num;state.observed_frames=1;state.confidence_sum=confidence;state.min_confidence=confidence;state.max_confidence=confidence;state.last_confidence=confidence;state.last_left=object->rect_params.left;state.last_top=object->rect_params.top;state.last_width=width;state.last_height=height;state.last_x=point.x;state.last_y=point.y;state.last_area=area;vehicle_quality_possible_id_switch(a,state,point,frame_num);a->vehicle_quality_tracks[state.object_id]=state;++a->vehicle_quality_tracks_total;if(state.class_id==CAR_CLASS_ID)++a->vehicle_quality_car_tracks;else if(state.class_id==MOTORCYCLE_CLASS_ID)++a->vehicle_quality_motorcycle_tracks;else if(state.class_id==BUS_CLASS_ID)++a->vehicle_quality_bus_tracks;vehicle_quality_snapshot("TRACK_START",state,object,point,frame_num);return;}VehicleQualityTrackState& state=it->second;const guint observation_gap=frame_num>state.last_seen_frame?frame_num-state.last_seen_frame-1:0;state.max_observation_gap=std::max(state.max_observation_gap,observation_gap);const float dx=point.x-state.last_x,dy=point.y-state.last_y,dw=std::fabs(width-state.last_width)/std::max(state.last_width,1.0f),dh=std::fabs(height-state.last_height)/std::max(state.last_height,1.0f),confidence_delta=confidence-state.last_confidence;++state.observed_frames;state.last_seen_frame=frame_num;state.confidence_sum+=confidence;state.min_confidence=std::min(state.min_confidence,confidence);state.max_confidence=std::max(state.max_confidence,confidence);if(std::fabs(confidence_delta)>VEHICLE_QUALITY_CONFIDENCE_DELTA){++a->vehicle_quality_confidence_changes;std::cout<<"VEHICLE_QUALITY_CONFIDENCE_CHANGE source_id=0 object_id="<<state.object_id<<" class="<<state.object_label<<" delta="<<std::fixed<<std::setprecision(3)<<confidence_delta<<" confidence="<<confidence<<" frame="<<frame_num<<'\n';}if(std::fabs(dx)>VEHICLE_QUALITY_POSITION_JUMP||std::fabs(dy)>VEHICLE_QUALITY_POSITION_JUMP||dw>VEHICLE_QUALITY_SIZE_JUMP||dh>VEHICLE_QUALITY_SIZE_JUMP){++a->vehicle_quality_bbox_jumps;std::cout<<"VEHICLE_QUALITY_JUMP source_id=0 object_id="<<state.object_id<<" class="<<state.object_label<<" dx="<<std::fixed<<std::setprecision(3)<<dx<<" dy="<<dy<<" dw="<<dw<<" dh="<<dh<<" confidence="<<confidence<<" frame="<<frame_num<<'\n';}state.last_confidence=confidence;state.last_left=object->rect_params.left;state.last_top=object->rect_params.top;state.last_width=width;state.last_height=height;state.last_x=point.x;state.last_y=point.y;state.last_area=area;if(state.observed_frames==5||state.observed_frames==15||state.observed_frames==30||state.observed_frames==60)vehicle_quality_snapshot("TRACK_CHECKPOINT",state,object,point,frame_num);}
void cleanup_vehicle_quality_tracks(App* a,guint frame_num){if(!a->vehicle_quality_debug)return;for(std::map<guint64,VehicleQualityTrackState>::iterator it=a->vehicle_quality_tracks.begin();it!=a->vehicle_quality_tracks.end();){if(frame_num>it->second.last_seen_frame+TRACK_STATE_STALE_FRAMES){vehicle_quality_track_end(a,it->second,"STALE_REMOVED");it=a->vehicle_quality_tracks.erase(it);}else ++it;}}
void finish_vehicle_quality_tracks(App* a){if(!a->vehicle_quality_debug)return;for(std::map<guint64,VehicleQualityTrackState>::iterator it=a->vehicle_quality_tracks.begin();it!=a->vehicle_quality_tracks.end();){vehicle_quality_track_end(a,it->second,"SHUTDOWN");it=a->vehicle_quality_tracks.erase(it);}}
void vehicle_quality_summary(const App* a){if(!a->vehicle_quality_debug)return;guint under5=0,from5to14=0,from15to29=0,from30to59=0,atleast60=0;double total=0.0;for(std::vector<guint>::const_iterator it=a->vehicle_quality_track_lengths.begin();it!=a->vehicle_quality_track_lengths.end();++it){total+=*it;if(*it<5)++under5;else if(*it<15)++from5to14;else if(*it<30)++from15to29;else if(*it<60)++from30to59;else ++atleast60;}double median=0.0;if(!a->vehicle_quality_track_lengths.empty()){std::vector<guint> lengths=a->vehicle_quality_track_lengths;std::sort(lengths.begin(),lengths.end());const size_t middle=lengths.size()/2;median=lengths.size()%2?lengths[middle]:(lengths[middle-1]+lengths[middle])/2.0;}const VehicleCounters& counters=a->vehicle_counters;std::cout<<"VEHICLE QUALITY SUMMARY\nvehicle tracks total: "<<a->vehicle_quality_tracks_total<<"\ncar tracks: "<<a->vehicle_quality_car_tracks<<"\nmotorcycle tracks: "<<a->vehicle_quality_motorcycle_tracks<<"\nbus tracks: "<<a->vehicle_quality_bus_tracks<<"\ntracks <5 frames: "<<under5<<"\ntracks 5-14 frames: "<<from5to14<<"\ntracks 15-29 frames: "<<from15to29<<"\ntracks 30-59 frames: "<<from30to59<<"\ntracks >=60 frames: "<<atleast60<<"\navg track length: "<<std::fixed<<std::setprecision(2)<<(a->vehicle_quality_track_lengths.empty()?0.0:total/a->vehicle_quality_track_lengths.size())<<"\nmedian track length: "<<median<<"\npossible id switches: "<<a->vehicle_quality_id_switches<<"\nbbox jumps: "<<a->vehicle_quality_bbox_jumps<<"\nconfidence changes: "<<a->vehicle_quality_confidence_changes<<"\nred crossings: "<<(counters.red_direction_1+counters.red_direction_2)<<"\ngreen crossings: "<<(counters.green_direction_1+counters.green_direction_2)<<"\nblue accepted crossings: "<<counters.blue_right_to_left<<"\nblue direction rejected: "<<counters.blue_direction_rejected<<'\n';}void stage7_geometry_debug(const App* a){if(!a->vehicle_line_debug)return;std::cout<<"STAGE7_GEOMETRY roi_pixels="<<kStage7Geometry.left<<";"<<kStage7Geometry.top<<";"<<kStage7Geometry.width<<";"<<kStage7Geometry.height<<" roi_normalized="<<std::fixed<<std::setprecision(9)<<kStage7Geometry.x_min<<","<<kStage7Geometry.y_min<<","<<kStage7Geometry.x_max<<","<<kStage7Geometry.y_max<<" red="<<kVehicleLines[VEHICLE_RED].start_x<<","<<kVehicleLines[VEHICLE_RED].start_y<<"->"<<kVehicleLines[VEHICLE_RED].end_x<<","<<kVehicleLines[VEHICLE_RED].end_y<<"\n";}void stage7_build_marker(){std::cout<<"STAGE7_BUILD_MARKER version=7D5 roi=1250,616,1140,824 geometry=FINAL\n";std::cout<<"STAGE7_RUNTIME_GEOMETRY roi_norm="<<std::fixed<<std::setprecision(9)<<kStage7Geometry.x_min<<","<<kStage7Geometry.y_min<<","<<kStage7Geometry.x_max<<","<<kStage7Geometry.y_max<<" red_A="<<kVehicleLines[VEHICLE_RED].start_x<<","<<kVehicleLines[VEHICLE_RED].start_y<<" red_B="<<kVehicleLines[VEHICLE_RED].end_x<<","<<kVehicleLines[VEHICLE_RED].end_y<<"\n";}void set_color(NvOSD_ColorParams* color,double red,double green,double blue,double alpha){color->red=red;color->green=green;color->blue=blue;color->alpha=alpha;}
void vehicle_line_zone_add_line(NvDsDisplayMeta* display,const Point& a,const Point& b,guint line_width,double red,double green,double blue,double alpha){NvOSD_LineParams& line=display->line_params[display->num_lines++];line.x1=static_cast<guint>(a.x);line.y1=static_cast<guint>(a.y);line.x2=static_cast<guint>(b.x);line.y2=static_cast<guint>(b.y);line.line_width=line_width;set_color(&line.line_color,red,green,blue,alpha);}
